import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{static void check(String input,Map<String,Integer>frequency,int optimalLength){Object r=TaskBinding.encode(input);Map<String,String>codes=TaskBinding.codes(r);assertEquals(frequency,TaskBinding.frequencies(r));assertEquals(frequency.keySet(),codes.keySet());for(var a:codes.entrySet()){assertTrue(a.getValue().matches("[01]+"));for(var b:codes.entrySet())if(!a.getKey().equals(b.getKey()))assertFalse(b.getValue().startsWith(a.getValue()));}String bits=TaskBinding.bits(r);assertTrue(bits.matches("[01]*"));assertEquals(optimalLength,bits.length());int weighted=0;for(String word:frequency.keySet())weighted+=frequency.get(word)*codes.get(word).length();assertEquals(optimalLength,weighted);Map<String,String>decoded=new HashMap<>();for(var e:codes.entrySet())assertNull(decoded.put(e.getValue(),e.getKey()));List<String>words=new ArrayList<>();String pending="";for(char bit:bits.toCharArray()){pending+=bit;if(decoded.containsKey(pending)){words.add(decoded.get(pending));pending="";}}assertEquals("",pending);assertEquals(input.isEmpty()?List.of():Arrays.asList(input.split(" +")),words);}@Test void reproducibleFreeTiesCaseAndAnotherHandOptimalCost(){String input="a b c d";check(input,Map.of("a",1,"b",1,"c",1,"d",1),8);assertEquals(TaskBinding.codes(TaskBinding.encode(input)),TaskBinding.codes(TaskBinding.encode(input)));check("a b c c d d d d",Map.of("a",1,"b",1,"c",2,"d",4),14);check("One one",Map.of("One",1,"one",1),2);}}
